// The guarded lane-wise helpers `main.ts` calls, in a dependency outside the
// program's no-panic scope; `main.ts`'s header says why they are proven.
import { bitmask, eq, loadU8x16, splatU8x16, store } from "nish:simd"

export const newlineMask = (xs: u8[]): i32 => {
  const newline = splatU8x16(10)
  let mask: i32 = 0
  let i: i32 = 0
  while (i >= 0 && i <= toI32(xs.length) - 16) {
    // One bit per newline among these sixteen bytes, lowest lane first; the
    // chunks' masks are folded together with xor, which cannot overflow.
    mask = mask ^ bitmask(eq(loadU8x16(xs, i), newline))
    i += 16
  }
  return mask
}

export const fillNewlines = (xs: u8[]): void => {
  const newline = splatU8x16(10)
  let i: i32 = 0
  while (i >= 0 && i <= toI32(xs.length) - 16) {
    store(newline, xs, i)
    i += 16
  }
}
